{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C37"],
      "claim": "Umeclidinium, a quaternary ammonium antimuscarinic, has systemic bioavailability ≤12% after oral administration in healthy volunteers, directly supporting low oral bioavailability for the permanently charged query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "DX-9065a, a strongly basic amidine-containing factor Xa inhibitor, has human oral bioavailability of only 2–3%, attributed to its strong basic groups; supports low F for a charged, poorly permeable cation.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Terfenadine has mean oral bioavailability <5% in humans due to extensive first-pass metabolism, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Pravastatin has absolute oral bioavailability about 18% in humans, below the 20% threshold, due to incomplete absorption and first-pass extraction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Propafenone at a 150 mg therapeutic oral dose has mean absolute bioavailability of 13% in humans, below the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Lercanidipine absolute bioavailability is about 10% in fed patients, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Propafenone in some individual patients showed absolute oral bioavailability of 76%, above threshold; this contradictory high value reflects variable CYP2D6-dependent first-pass metabolism rather than a general high-F property.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C19"],
      "claim": "Lercanidipine after a single 10 mg oral dose showed about 30% absolute bioavailability in healthy volunteers/patients, above threshold; this contradictory record is condition-dependent and outweighed by fed-state low-F data.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a permanently quaternary ammonium tropane ester, a charge state strongly associated with poor membrane permeability and low oral absorption. High-transfer human evidence from quaternary/strongly basic or poorly absorbed drugs (umeclidinium ≤12%, DX-9065a 2–3%, terfenadine <5%, pravastatin ~18%, propafenone mean 13%, fed lercanidipine 10%) consistently indicates F <20%. The few above-threshold values (propafenone individuals 60–76%, lercanidipine 30%) are metabolism- or condition-dependent and do not outweigh the charge-based low-F expectation. Prediction: low.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the exact query molecule.",
    "The query's formulation, salt form, and fed/fasted state are unspecified; these can affect absorption of quaternary ammonium drugs.",
    "Transporter-mediated efflux (e.g., P-gp) for the query is inferred from analogs, not directly measured.",
    "Most evidence comes from different scaffolds; transfer scores are high but not direct."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

